import json
SUCCESS_RESPONSE = {
    'status': 'success',
    'message': 'Data received successfully.'
}
def task_func():
    class RequestHandler(http.server.BaseHTTPRequestHandler):
        def _send_response(self, code, message):
            self.send_response(code)
            self.send_header('Content-Type', 'application/json')
            self.end_headers()
            response_body = json.dumps(message).encode()
            self.wfile.write(response_body)

        def do_POST(self):
            if self.headers.get('Content-Type') != 'application/json':
                self._send_response(400, {'status': 'error', 'message': 'Content-Type header is not application/json'})
                return
            content_length = int(self.headers.get('Content-Length', 0))
            try:
                body = self.rfile.read(content_length).decode()
                data = json.loads(body)
            except (json.JSONDecodeError, UnicodeDecodeError):
                self._send_response(400, {'status': 'error', 'message': 'Invalid JSON'})
                return
            if 'data' not in data:
                self._send_response(400, {'status': 'error', 'message': 'No data key in request'})
                return
            self._send_response(200, SUCCESS_RESPONSE)

